{
  "requirement_definitions": [
    {
      "id": "SVC-COMCCSDSSDLS-001",
      "title": "CCSDS stack composition with SDLS decryption",
      "text": "The subtopology shall provide the standard CCSDS framing/deframing communications stack by composing the `ComCcsds.SpacePacketFraming` and `ComCcsds.TmTcFraming` layer topologies, with SDLS decryption inserted in the uplink path."
    },
    {
      "id": "SVC-COMCCSDSSDLS-002",
      "title": "Uplink SDLS deframing and decryption",
      "text": "The uplink path shall pass TC-deframed data through a `Svc.Ccsds.CcsdsSdlsDeframer`, which extracts the SA index and delegates decryption before Space Packet deframing."
    },
    {
      "id": "SVC-COMCCSDSSDLS-003",
      "title": "SA-indexed decryption routing",
      "text": "Decryption requests shall be routed by SA index through a `Svc.Ccsds.SdlsSaRouter` to downstream decryptor instances."
    },
    {
      "id": "SVC-COMCCSDSSDLS-004",
      "title": "Configurable decryptor selection",
      "text": "The decryptor choice shall be configurable via the subtopology configuration module, defaulting to `Svc.Ccsds.ClearTextDecryptor`."
    },
    {
      "id": "SVC-COMCCSDSSDLS-005",
      "title": "Default SA mapping and security replacement",
      "text": "The default SA map shall route SA 1 to the `PLAINTEXT` port (the default decryptor/encryptor); SA 0, reserved by CCSDS 355.0-B-2 for Extended Procedures, shall route to a port left unconnected. Any SA mapped to a `ClearText*` component is an unauthenticated path; deployments requiring security shall replace the default component (see 2.4)."
    },
    {
      "id": "SVC-COMCCSDSSDLS-006",
      "title": "Subtopology variants",
      "text": "The module shall provide a `FramingSubtopology` (external `Svc.ComInterface`) and a `Subtopology` (supplies `Svc::ComStub`) variant, mirroring ComCcsds."
    },
    {
      "id": "SVC-COMCCSDSSDLS-007",
      "title": "SDLS instance configuration",
      "text": "The SDLS instance properties (base ID, decryptor and encryptor selection) shall be configurable via a `ComCcsdsSdlsConfig` module; the reused packet and frame layer instances remain configurable via `ComCcsdsConfig`."
    }
  ],
  "allocation_entries": []
}
